from itertools import combinations
from random import Random


def _line_content(inp: str) -> str:
    if inp.endswith("\r\n"):
        return inp[:-2]
    if inp.endswith("\n"):
        return inp[:-1]
    return inp


def validate_input(inp: str) -> bool:
    s = _line_content(inp)
    return 1 <= len(s) <= 100 and all(c in "io" for c in s)


def gen_small(seed: int, n: int) -> list[str]:
    rng = Random(seed)
    cases = [
        "i", "o", "io", "oi", "ii", "oo", "ioi", "iioo",
        "iiiiiiii", "oooooooo", "ioioioio", "oioioioi",
        "ooooiiii", "iiiioooo",
    ]
    result = []
    for index in range(n):
        if index < len(cases):
            s = cases[index]
        else:
            s = "".join(rng.choice("io") for _ in range(rng.randint(1, 8)))
        ending = ("\n", "", "\r\n")[index % 3]
        result.append(s + ending)
    return result


def gen_stress(seed: int) -> list[str]:
    rng = Random(seed)
    single_run = rng.choice("io") * 100
    split = rng.randint(35, 65)
    reversed_runs = "o" * split + "i" * (99 - split)
    return [single_run + "\n", reversed_runs + "\n"]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    if not validate_input(inp):
        return [("POST-1", "Input must contain one line of 1–100 i/o characters.")]
    tokens = out.split()
    if len(tokens) != 1 or any(c not in "0123456789" for c in tokens[0]):
        return [("POST-2", "Expected one nonnegative decimal integer.")]

    s = _line_content(inp)
    n = len(s)
    digits = tokens[0].lstrip("0") or "0"
    if len(digits) > len(str(n)):
        return [("POST-3", "The reported insertion count exceeds the input length.")]
    k = int(digits)
    if k > n:
        return [("POST-3", "The reported insertion count exceeds the input length.")]

    violations = []
    completed_length = n + k
    if completed_length % 2:
        violations.append(("POST-3", "The completed length must be even."))
    elif max(s.count("i"), s.count("o")) > completed_length // 2:
        violations.append(("POST-3", "The completed string has too few positions for one character."))
    already_valid = n % 2 == 0 and s == "io" * (n // 2)
    if (k == 0) != already_valid:
        violations.append(("POST-3", "Zero insertions are required exactly for an already valid input."))
    return violations


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    pairs = []
    for index, inp in enumerate(gen_small(seed, n)):
        s = _line_content(inp)
        if index % 2 == 0:
            # The prepended pair can occupy the first two positions.
            # In any embedding, its o consumes at least the first pair.
            transformed = "io" + s
        else:
            # Reversing and swapping preserves the target pattern
            # and gives a bijection between completions.
            transformed = "".join("o" if c == "i" else "i" for c in reversed(s))
            if transformed == s:
                transformed = "io" + s
        pairs.append(("POST-4", "equal", inp, transformed + "\n"))
    return pairs


def reference_small(inp: str) -> str | None:
    if not validate_input(inp):
        return None
    s = _line_content(inp)
    n = len(s)
    if n > 8:
        return None
    for completed_length in range(n, 2 * n + 1):
        if completed_length % 2:
            continue
        target = "io" * (completed_length // 2)
        for original_positions in combinations(range(completed_length), n):
            if "".join(target[p] for p in original_positions) == s:
                return str(completed_length - n) + "\n"
    return None
